import json, sys
from collections import defaultdict

def process_ledger(data: dict) -> dict:
    balances: dict[str, int] = defaultdict(int)
    unbalanced: list[str] = []
    for entry in data.get('entries', []):
        lines = entry.get('lines', [])
        debits = sum(l['amount_cents'] for l in lines if l['type'] == 'DEBIT')
        credits = sum(l['amount_cents'] for l in lines if l['type'] == 'CREDIT')
        if len(lines) < 2 or debits != credits:
            unbalanced.append(entry['entry_id'])
            continue
        for l in lines:
            delta = l['amount_cents'] if l['type'] == 'DEBIT' else -l['amount_cents']
            balances[l['account']] += delta
    return {'balances': dict(sorted(balances.items())), 'unbalanced_entries': unbalanced}
